"""Corpus manifests: metadata for every PDF in a corpus.

Two corpora live side by side and never share a directory:

* ``synthetic`` (``data/synthetic``) — generated by ``generate_corpus.py`` for
  the demo and the regression evaluation. The manifest is committed; the PDFs
  are regenerated deterministically from the seed and are not.
* ``real`` (``data/real_sources``) — official regulator documents for the
  research evaluation. The manifest records where and when each document was
  fetched and its checksum; the PDFs are fetched, not committed
  (``scrape_sebi.py``).
"""

from __future__ import annotations

import json
from dataclasses import asdict, dataclass
from datetime import date
from pathlib import Path
from typing import Literal

ROOT = Path(__file__).resolve().parents[1]
CorpusName = Literal["synthetic", "real"]
_CORPUS_DIRS: dict[str, Path] = {
    "synthetic": ROOT / "data" / "synthetic",
    "real": ROOT / "data" / "real_sources",
}


@dataclass(frozen=True)
class CorpusPaths:
    root: Path
    pdf_dir: Path
    manifest: Path


def corpus_paths(name: CorpusName) -> CorpusPaths:
    root = _CORPUS_DIRS[name]
    return CorpusPaths(root=root, pdf_dir=root / "pdf", manifest=root / "manifest.jsonl")


@dataclass
class ManifestEntry:
    circular_number: str
    title: str
    issue_date: str | None  # ISO-8601; str so the manifest is plain JSON
    department: str | None
    doc_type: str
    source_url: str
    pdf_filename: str
    # Real-source provenance; absent for synthetic entries. ``source_url`` is
    # the PDF itself; ``page_url`` the regulator's page that publishes it.
    page_url: str | None = None
    retrieved_on: str | None = None
    sha256: str | None = None
    note: str | None = None

    @property
    def parsed_date(self) -> date | None:
        return date.fromisoformat(self.issue_date) if self.issue_date else None


_REQUIRED = {"circular_number", "title", "issue_date", "department", "doc_type", "source_url"}


def write_manifest(entries: list[ManifestEntry], path: Path) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8") as handle:
        for entry in entries:
            # Optional provenance fields are omitted when unset; required ones never are.
            row = {k: v for k, v in asdict(entry).items() if v is not None or k in _REQUIRED}
            handle.write(json.dumps(row, ensure_ascii=False) + "\n")


def read_manifest(path: Path) -> list[ManifestEntry]:
    if not path.is_file():
        return []
    entries: list[ManifestEntry] = []
    with path.open(encoding="utf-8") as handle:
        for line in handle:
            line = line.strip()
            if line:
                entries.append(ManifestEntry(**json.loads(line)))
    return entries
